"""Real JEE Main questions — Mathematics Unit 2: Complex Numbers and Quadratic Equations. Our own solutions; chk re-solves
each one with Python's complex arithmetic — loci by sampling points, polynomial roots with numpy-free formulas or by
scanning, recurrences by actually computing α^n + β^n. Skipped: items whose options are cut in the scan, an item whose
printed expression does not match any option, and limit-based items (later units)."""
import cmath, math, itertools
from fractions import Fraction as F
from common import new_registry, pick, near, verify
P, add = new_registry()
def qroots(a, b, c):
    d = cmath.sqrt(b * b - 4 * a * c); return (-b + d) / (2 * a), (-b - d) / (2 * a)
def grid(lo, hi, n): return [lo + (hi - lo) * i / (n - 1) for i in range(n)]
def circle(c, r, n=3600): return [c + r * cmath.exp(2j * math.pi * k / n) for k in range(n)]
W = cmath.exp(2j * math.pi / 3)

